# Generated by AI (Claude, Anthropic). Apache-2.0.
#
# Browsers for the "browser" mode, sourced by stream.sh.
# id | kind (chromium/firefox) | commands | flatpak app id
BROWSER_TABLE="
brave|chromium|brave-browser brave|com.brave.Browser
chrome|chromium|google-chrome-stable google-chrome|com.google.Chrome
chromium|chromium|chromium-browser chromium|org.chromium.Chromium
vivaldi|chromium|vivaldi-stable vivaldi|com.vivaldi.Vivaldi
edge|chromium|microsoft-edge-stable microsoft-edge|com.microsoft.Edge
firefox|firefox|firefox|org.mozilla.firefox
librewolf|firefox|librewolf|io.gitlab.librewolf-community
zen|firefox|zen-browser zen|app.zen_browser.zen
"
PROFILES=~/.local/share/vrchat-stream/browsers

# Sets B_KIND and B_CMD (array) for browser id $1; fails if it isn't installed
find_browser() {
    local id kind cmds app c
    while IFS='|' read -r id kind cmds app; do
        [ "$id" = "$1" ] || continue
        B_KIND=$kind
        for c in $cmds; do
            command -v "$c" >/dev/null && { B_CMD=("$c"); return 0; }
        done
        if command -v flatpak >/dev/null && flatpak info "$app" >/dev/null 2>&1; then
            # The sandbox must see the Xwayland window and our profile folder,
            # and must not run on the real Wayland desktop instead
            B_CMD=(flatpak run --nosocket=wayland --socket=x11 --filesystem="$PROFILES"
                   --env=DISPLAY="$DISP" --env=PULSE_SINK="$SINK" --env=MOZ_ENABLE_WAYLAND=0 "$app")
            return 0
        fi
        return 1
    done <<<"$BROWSER_TABLE"
    return 1
}

# Supported browser that is the desktop's default, if any
default_browser() {
    local desktop id
    # Over SSH xdg-settings may not know the desktop and answer something
    # unrelated, so ask about https links first and use both answers
    desktop="$(xdg-mime query default x-scheme-handler/https 2>/dev/null) $(xdg-settings get default-web-browser 2>/dev/null)"
    desktop=${desktop,,}
    for id in zen librewolf firefox brave vivaldi edge chrome chromium; do
        case $desktop in
            *"$id"*) find_browser $id && { echo $id; return; } ;;
        esac
    done
}

installed_browsers() {
    local id _rest
    while IFS='|' read -r id _rest; do
        [ -n "$id" ] && find_browser "$id" && echo "$id"
    done <<<"$BROWSER_TABLE"
}

# Chooses the browser for $1 (auto / default / an id) → B_ID, B_KIND, B_CMD
pick_browser() {
    B_ID=
    if [ "$1" != auto ] && [ "$1" != default ]; then
        find_browser "$1" && B_ID=$1
        return
    fi
    B_ID=$(default_browser)
    [ -n "$B_ID" ] || B_ID=$(installed_browsers | head -1)
    [ -n "$B_ID" ] && find_browser "$B_ID"
}

# Starts the picked browser in the Xwayland window, sound into $SINK
launch_browser() {
    local profile=$PROFILES/$B_ID
    mkdir -p "$profile"
    if [ "$B_KIND" = firefox ]; then
        cat >"$profile/user.js" <<EOF
user_pref("media.autoplay.default", 0);
user_pref("media.autoplay.blocking_policy", 0);
user_pref("browser.shell.checkDefaultBrowser", false);
user_pref("browser.aboutwelcome.enabled", false);
user_pref("datareporting.policy.dataSubmissionPolicyBypassNotification", true);
user_pref("browser.startup.homepage_override.mstone", "ignore");
user_pref("trailhead.firstrun.didSeeAboutWelcome", true);
user_pref("zen.welcome-screen.seen", true);
EOF
        # There is no window manager in the Xwayland window: tell Firefox
        # itself where its window goes and how big it is
        printf '{"chrome://browser/content/browser.xhtml":{"main-window":{"screenX":"0","screenY":"0","width":"%s","height":"%s","sizemode":"normal"}}}' \
            $W $H >"$profile/xulstore.json"
        DISPLAY=$DISP PULSE_SINK=$SINK MOZ_ENABLE_WAYLAND=0 "${B_CMD[@]}" \
            --no-remote --new-instance --profile "$profile" --width $W --height $H \
            ${START_URL:+"$START_URL"}
    else
        DISPLAY=$DISP PULSE_SINK=$SINK "${B_CMD[@]}" --ozone-platform=x11 \
            --user-data-dir="$profile" --no-first-run --no-default-browser-check \
            --window-position=0,0 --window-size=$W,$H \
            --autoplay-policy=no-user-gesture-required ${START_URL:+"$START_URL"}
    fi
}
